import React, { useEffect, useState } from "react"
import { format } from "date-fns"
import { doc, getDoc } from "firebase/firestore"
import { db } from "../../../firebase/config"
import { Appointment, AppointmentStatus } from "../../../hooks/useAppointments"
import { ServiceTicket, getTicketByAppointment, updateTicket } from "../../../hooks/useServiceTickets"
import { useSettings } from "../../../hooks/useSettings"
import { useToast } from "../../../context/ToastContext"
import { Vehicle } from "../../../hooks/useClients"

interface Props {
  appointment: Appointment
  onClose: () => void
  onStatusChange: (appointmentId: string, status: AppointmentStatus) => Promise<void>
}

const STATUS_FLOW: AppointmentStatus[] = [
  "scheduled",
  "confirmed",
  "in-progress",
  "completed",
]

const STATUS_LABELS: Record<AppointmentStatus, string> = {
  scheduled: "Scheduled",
  confirmed: "Confirmed",
  "pending-approval": "Pending Approval",
  "in-progress": "In Progress",
  completed: "Completed",
  cancelled: "Cancelled",
}

const STATUS_COLORS: Record<AppointmentStatus, string> = {
  scheduled: "bg-blue-100 text-blue-700",
  confirmed: "bg-green-100 text-green-700",
  "pending-approval": "bg-yellow-100 text-yellow-700",
  "in-progress": "bg-purple-100 text-purple-700",
  completed: "bg-gray-100 text-gray-600",
  cancelled: "bg-red-100 text-red-600",
}

function fmt(n: number) {
  return `$ ${n.toLocaleString("en-CA", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
}

function round2(n: number) {
  return Math.round(n * 100) / 100
}

export default function AppointmentDetailModal({ appointment, onClose, onStatusChange }: Props) {
  const { showToast } = useToast()
  const { taxes, services } = useSettings()

  const [ticket, setTicket] = useState<ServiceTicket | null>(null)
  const [vehicles, setVehicles] = useState<Vehicle[]>([])
  const [loadingTicket, setLoadingTicket] = useState(true)

  // Ticket form state
  const [vehicleId, setVehicleId] = useState("")
  const [billable, setBillable] = useState("")
  const [nonBillable, setNonBillable] = useState("")
  const [customDesc, setCustomDesc] = useState("")
  const [ticketDirty, setTicketDirty] = useState(false)
  const [savingTicket, setSavingTicket] = useState(false)

  // Status state
  const [status, setStatus] = useState<AppointmentStatus>(appointment.status)
  const [savingStatus, setSavingStatus] = useState(false)

  // Load ticket + client vehicles
  useEffect(() => {
    let cancelled = false
    async function load() {
      setLoadingTicket(true)
      const t = await getTicketByAppointment(appointment.id)
      if (cancelled) return

      if (t) {
        setTicket(t)
        setVehicleId(t.vehicleId ?? "")
        setBillable(String(t.billableAmount))
        setNonBillable(String(t.nonBillableAmount))
        setCustomDesc(t.customServiceDescription ?? "")
      }

      // Load client vehicles
      if (db && appointment.clientId) {
        const snap = await getDoc(doc(db, "clients", appointment.clientId))
        if (!cancelled && snap.exists()) {
          setVehicles(snap.data().vehicles ?? [])
        }
      }
      if (!cancelled) setLoadingTicket(false)
    }
    load()
    return () => { cancelled = true }
  }, [appointment.id, appointment.clientId])

  // Close on Escape
  useEffect(() => {
    function onKey(e: KeyboardEvent) { if (e.key === "Escape") onClose() }
    document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [onClose])

  // Live tax preview
  const billableNum = parseFloat(billable) || 0
  const nonBillableNum = parseFloat(nonBillable) || 0
  const gst = round2(billableNum * taxes.GST / 100)
  const qst = round2(billableNum * taxes.QST / 100)
  const total = round2(billableNum + gst + qst + nonBillableNum)

  function markDirty() { setTicketDirty(true) }

  async function handleSaveTicket() {
    if (!ticket) return
    setSavingTicket(true)
    try {
      await updateTicket(ticket.id, {
        vehicleId,
        billableAmount: billableNum,
        nonBillableAmount: nonBillableNum,
        taxGST: gst,
        taxQST: qst,
        customServiceDescription: customDesc,
      })
      setTicket(prev => prev ? {
        ...prev,
        vehicleId,
        billableAmount: billableNum,
        nonBillableAmount: nonBillableNum,
        taxGST: gst,
        taxQST: qst,
        customServiceDescription: customDesc,
      } : prev)
      setTicketDirty(false)
      showToast("Ticket saved", "success")
    } catch {
      showToast("Failed to save ticket", "error")
    } finally {
      setSavingTicket(false)
    }
  }

  async function handleStatusChange(next: AppointmentStatus) {
    setSavingStatus(true)
    try {
      await onStatusChange(appointment.id, next)
      // When completing, also complete the ticket
      if (next === "completed" && ticket) {
        await updateTicket(ticket.id, { status: "completed" })
        setTicket(prev => prev ? { ...prev, status: "completed" } : prev)
      }
      setStatus(next)
      showToast(`Status updated to ${STATUS_LABELS[next]}`, "success")
    } catch {
      showToast("Failed to update status", "error")
    } finally {
      setSavingStatus(false)
    }
  }

  const serviceLabel = appointment.serviceType === "custom"
    ? customDesc || "Custom Service"
    : services.find(s => s.id === appointment.serviceType)?.label
      ?? appointment.serviceType.replace(/-/g, " ").replace(/\b\w/g, c => c.toUpperCase())

  const selectedVehicle = vehicles.find(v => v.vehicleId === vehicleId)

  const isCompleted = status === "completed"
  const isCancelled = status === "cancelled"
  const isEditable = !isCompleted && !isCancelled

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/50" onClick={onClose} />
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-lg max-h-[92vh] flex flex-col">

        {/* Header */}
        <div className="flex items-start justify-between px-6 py-4 border-b border-gray-100 flex-shrink-0">
          <div>
            <h2 className="font-semibold text-gray-800">{appointment.clientName}</h2>
            <p className="text-xs text-gray-400 mt-0.5">
              {format(appointment.date, "EEEE, MMMM d, yyyy")} at {appointment.timeSlot}
            </p>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-700 text-xl leading-none ml-4">✕</button>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-5 space-y-6">

          {/* ── Status ── */}
          <section>
            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-3">Status</h3>
            <div className="flex flex-wrap gap-2">
              {STATUS_FLOW.map(s => (
                <button
                  key={s}
                  onClick={() => !savingStatus && s !== status && handleStatusChange(s)}
                  disabled={savingStatus || isCompleted || isCancelled}
                  className={`px-3 py-1.5 rounded-lg text-xs font-medium border transition-colors disabled:cursor-not-allowed ${
                    status === s
                      ? `${STATUS_COLORS[s]} border-transparent ring-2 ring-offset-1 ring-current`
                      : "border-gray-200 text-gray-500 hover:bg-gray-50 disabled:opacity-40"
                  }`}
                >
                  {STATUS_LABELS[s]}
                </button>
              ))}

              {/* Separate cancel button */}
              {!isCompleted && !isCancelled && (
                <button
                  onClick={() => handleStatusChange("cancelled")}
                  disabled={savingStatus}
                  className="px-3 py-1.5 rounded-lg text-xs font-medium border border-red-200 text-red-500 hover:bg-red-50 transition-colors disabled:opacity-40 ml-auto"
                >
                  Cancel appointment
                </button>
              )}
              {(isCompleted || isCancelled) && (
                <span className={`text-xs px-3 py-1.5 rounded-lg font-medium ${STATUS_COLORS[status]}`}>
                  {STATUS_LABELS[status]}
                </span>
              )}
            </div>
            {savingStatus && (
              <p className="text-xs text-gray-400 mt-2">Saving…</p>
            )}
          </section>

          {/* ── Service info ── */}
          <section>
            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-3">Service</h3>
            <div className="bg-gray-50 rounded-lg p-3 text-sm space-y-1">
              <p className="font-medium text-gray-800 capitalize">{serviceLabel}</p>
              {appointment.estimatedDuration > 0 && (
                <p className="text-gray-400 text-xs">Est. {appointment.estimatedDuration} min</p>
              )}
              {appointment.notes && (
                <p className="text-gray-600 text-xs italic mt-1">"{appointment.notes}"</p>
              )}
            </div>
          </section>

          {/* ── Service ticket ── */}
          <section>
            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-3">
              Service Ticket
              {ticket && (
                <span className={`ml-2 normal-case font-medium px-1.5 py-0.5 rounded text-[10px] ${
                  ticket.status === "completed" ? "bg-green-100 text-green-700" : "bg-yellow-100 text-yellow-700"
                }`}>
                  {ticket.status}
                </span>
              )}
            </h3>

            {loadingTicket ? (
              <div className="h-6 bg-gray-100 rounded animate-pulse" />
            ) : !ticket ? (
              <p className="text-sm text-gray-400">No service ticket found for this appointment.</p>
            ) : (
              <div className="space-y-4">
                {/* Vehicle */}
                {vehicles.length > 0 && (
                  <div>
                    <label className="block text-xs font-medium text-gray-600 mb-1">Vehicle</label>
                    {isEditable ? (
                      <select
                        value={vehicleId}
                        onChange={e => { setVehicleId(e.target.value); markDirty() }}
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white"
                      >
                        <option value="">— No vehicle selected —</option>
                        {vehicles.map(v => (
                          <option key={v.vehicleId} value={v.vehicleId}>
                            {v.year} {v.make} {v.model}{v.color ? ` — ${v.color}` : ""}
                          </option>
                        ))}
                      </select>
                    ) : (
                      <p className="text-sm text-gray-700">
                        {selectedVehicle
                          ? `${selectedVehicle.year} ${selectedVehicle.make} ${selectedVehicle.model}`
                          : "—"}
                      </p>
                    )}
                  </div>
                )}

                {/* Custom description */}
                {appointment.serviceType === "custom" && (
                  <div>
                    <label className="block text-xs font-medium text-gray-600 mb-1">Service description</label>
                    {isEditable ? (
                      <input
                        type="text"
                        value={customDesc}
                        onChange={e => { setCustomDesc(e.target.value); markDirty() }}
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                      />
                    ) : (
                      <p className="text-sm text-gray-700">{customDesc || "—"}</p>
                    )}
                  </div>
                )}

                {/* Amounts */}
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-xs font-medium text-gray-600 mb-1">Billable ($)</label>
                    {isEditable ? (
                      <input
                        type="number"
                        min="0"
                        step="0.01"
                        value={billable}
                        onChange={e => { setBillable(e.target.value); markDirty() }}
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                      />
                    ) : (
                      <p className="text-sm text-gray-700">{fmt(billableNum)}</p>
                    )}
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-600 mb-1">Non-billable ($)</label>
                    {isEditable ? (
                      <input
                        type="number"
                        min="0"
                        step="0.01"
                        value={nonBillable}
                        onChange={e => { setNonBillable(e.target.value); markDirty() }}
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                      />
                    ) : (
                      <p className="text-sm text-gray-700">{fmt(nonBillableNum)}</p>
                    )}
                  </div>
                </div>

                {/* Tax summary */}
                <div className="bg-gray-50 rounded-lg p-3 space-y-1.5 text-sm font-mono">
                  <div className="flex justify-between text-gray-500 text-xs">
                    <span>GST ({taxes.GST}%)</span>
                    <span>{fmt(gst)}</span>
                  </div>
                  <div className="flex justify-between text-gray-500 text-xs">
                    <span>QST ({taxes.QST}%)</span>
                    <span>{fmt(qst)}</span>
                  </div>
                  {nonBillableNum > 0 && (
                    <div className="flex justify-between text-gray-500 text-xs">
                      <span>Non-billable</span>
                      <span>{fmt(nonBillableNum)}</span>
                    </div>
                  )}
                  <div className="flex justify-between font-bold text-gray-800 border-t border-gray-200 pt-1.5">
                    <span>Total</span>
                    <span>{fmt(total)}</span>
                  </div>
                </div>

                {isEditable && ticketDirty && (
                  <button
                    onClick={handleSaveTicket}
                    disabled={savingTicket}
                    className="w-full py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors disabled:opacity-50"
                  >
                    {savingTicket ? "Saving…" : "Save Ticket"}
                  </button>
                )}

                {isCompleted && (
                  <p className="text-xs text-green-600 font-medium text-center">
                    ✓ Service completed
                  </p>
                )}
              </div>
            )}
          </section>

        </div>
      </div>
    </div>
  )
}
