import React, { useState, useEffect, useRef } from "react"
import { Client, searchClients } from "../../../hooks/useClients"

// Firestore does not support full-text search. This implementation uses prefix
// match on the `name` field in alphabetical order. For advanced search consider
// Algolia or Typesense.

interface ClientSearchProps {
  onSelect: (client: Client) => void
  onCreateNew: () => void
}

export default function ClientSearch({ onSelect, onCreateNew }: ClientSearchProps) {
  const [query, setQuery] = useState("")
  const [results, setResults] = useState<Client[]>([])
  const [loading, setLoading] = useState(false)
  const [showDropdown, setShowDropdown] = useState(false)
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current)

    if (!query.trim()) {
      setResults([])
      setShowDropdown(false)
      return
    }

    debounceRef.current = setTimeout(async () => {
      setLoading(true)
      try {
        const found = await searchClients(query.trim())
        setResults(found)
        setShowDropdown(true)
      } catch {
        setResults([])
      } finally {
        setLoading(false)
      }
    }, 300)

    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current)
    }
  }, [query])

  function firstVehicleSummary(client: Client): string {
    if (!client.vehicles.length) return "No vehicles on file"
    const v = client.vehicles[0]
    return `${v.year} ${v.make} ${v.model}`
  }

  return (
    <div className="flex flex-col gap-4">
      <div className="relative">
        <input
          type="text"
          value={query}
          onChange={e => setQuery(e.target.value)}
          placeholder="Search by name or phone…"
          className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          autoFocus
        />
        {loading && (
          <div className="absolute right-3 top-1/2 -translate-y-1/2">
            <div className="w-4 h-4 border-2 border-blue-400 border-t-transparent rounded-full animate-spin" />
          </div>
        )}

        {showDropdown && (
          <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-gray-200 rounded-lg shadow-lg z-10 max-h-56 overflow-y-auto">
            {results.length === 0 ? (
              <div className="px-4 py-3 text-sm text-gray-500">No clients found</div>
            ) : (
              results.map(client => (
                <button
                  key={client.id}
                  onClick={() => {
                    onSelect(client)
                    setShowDropdown(false)
                  }}
                  className="w-full text-left px-4 py-3 hover:bg-gray-50 border-b border-gray-100 last:border-0 transition-colors"
                >
                  <p className="text-sm font-medium text-gray-800">{client.name}</p>
                  <p className="text-xs text-gray-500">
                    {client.phone} · {firstVehicleSummary(client)}
                  </p>
                </button>
              ))
            )}
          </div>
        )}
      </div>

      <button
        onClick={onCreateNew}
        className="text-sm text-blue-600 hover:text-blue-700 font-medium text-left transition-colors"
      >
        + Create New Client
      </button>
    </div>
  )
}
