import React, { useEffect, useState } from "react"
import { doc, getDoc, updateDoc, arrayUnion } from "firebase/firestore"
import { db } from "../../../firebase/config"
import { Appointment, AppointmentStatus } from "../../../hooks/useAppointments"
import { formatDayHeader } from "../../../utils/dateUtils"
import { generatePortalToken, isTokenExpired } from "../../../utils/tokenUtils"
import { STATUS_COLORS } from "./CalendarGrid"
import AppointmentWizard from "../Appointments/AppointmentWizard"
import AppointmentDetailModal from "../Appointments/AppointmentDetailModal"
import { useToast } from "../../../context/ToastContext"

interface DayPanelProps {
  date: Date | null
  appointments: Appointment[]
  onClose: () => void
  onStatusChange: (appointmentId: string, status: AppointmentStatus) => Promise<void>
}

const STATUS_LABELS: Record<AppointmentStatus, string> = {
  scheduled: "Scheduled",
  confirmed: "Confirmed",
  "pending-approval": "Pending",
  "in-progress": "In Progress",
  completed: "Completed",
  cancelled: "Cancelled",
}

interface PortalToken {
  token: string
  createdAt: { toDate: () => Date }
  expiresAt: { toDate: () => Date }
  used: boolean
  lastUsedAt: { toDate: () => Date } | null
}

interface ClientData {
  email: string
  name: string
  portalTokens: PortalToken[]
  activeTokenRef?: string | null
}

function SendPortalButton({ appt }: { appt: Appointment }) {
  const { showToast } = useToast()
  const [sending, setSending] = useState(false)

  async function handleSend() {
    if (!db) return
    setSending(true)
    try {
      const clientSnap = await getDoc(doc(db, "clients", appt.clientId))
      if (!clientSnap.exists()) { showToast("Client not found", "error"); return }
      const client = clientSnap.data() as ClientData

      if (!client.email) { showToast("Client has no email address", "error"); return }

      const tokens: PortalToken[] = client.portalTokens ?? []
      const hasValid = tokens.some(t => !isTokenExpired(t.expiresAt))
      if (hasValid) {
        const confirmed = window.confirm(
          "An active portal link already exists for this client. Send a new one anyway?"
        )
        if (!confirmed) return
      }

      const token = generatePortalToken()
      const now = new Date()
      const expiresAt = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000)

      await updateDoc(doc(db, "clients", appt.clientId), {
        portalTokens: arrayUnion({ token, createdAt: now, expiresAt, used: false, lastUsedAt: null }),
        activeTokenRef: token,
      })

      const apiBase = (process.env.GATSBY_API_URL ?? "").replace(/\/$/, "")
      const res = await fetch(`${apiBase}/api/send-portal-email`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          clientEmail: client.email,
          clientName: client.name,
          token,
          appointmentDate: appt.date instanceof Date
            ? appt.date.toISOString()
            : (appt.date as { toDate: () => Date }).toDate().toISOString(),
          shopName: "Garage Carlos Inc.",
          shopPhone: "",
        }),
      })

      if (!res.ok) {
        const data = await res.json().catch(() => ({}))
        throw new Error(data.error ?? "Send failed")
      }

      showToast(`Portal link sent to ${client.email}`, "success")
    } catch (err) {
      console.error(err)
      showToast("Failed to send. Please try again.", "error")
    } finally {
      setSending(false)
    }
  }

  return (
    <button
      onClick={handleSend}
      disabled={sending}
      className="text-xs px-2 py-1 rounded border border-blue-200 text-blue-600 hover:bg-blue-50 transition-colors disabled:opacity-50 flex items-center gap-1 flex-shrink-0"
      title="Send portal link to client"
    >
      {sending ? (
        <>
          <span className="w-3 h-3 border-2 border-blue-400 border-t-transparent rounded-full animate-spin" />
          Sending…
        </>
      ) : "📧 Portal"}
    </button>
  )
}

export default function DayPanel({ date, appointments, onClose, onStatusChange }: DayPanelProps) {
  const isOpen = date !== null
  const [showWizard, setShowWizard] = useState(false)
  const [selectedAppt, setSelectedAppt] = useState<Appointment | null>(null)

  useEffect(() => {
    setShowWizard(false)
    setSelectedAppt(null)
  }, [date])

  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape" && !showWizard && !selectedAppt) onClose()
    }
    if (isOpen) document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [isOpen, onClose, showWizard, selectedAppt])

  const sorted = [...appointments].sort((a, b) => a.timeSlot.localeCompare(b.timeSlot))

  return (
    <>
      {isOpen && !showWizard && !selectedAppt && (
        <div className="fixed inset-0 bg-black/40 z-30 md:hidden" onClick={onClose} />
      )}

      <div
        className={`fixed top-0 right-0 h-full z-40 flex flex-col bg-white shadow-xl transition-transform duration-300 ease-in-out
          w-full md:w-[380px]
          ${isOpen ? "translate-x-0" : "translate-x-full"}`}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100 flex-shrink-0">
          <h2 className="font-semibold text-gray-800 text-sm">
            {date ? formatDayHeader(date) : ""}
          </h2>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-700 text-xl leading-none transition-colors"
            aria-label="Close panel"
          >
            ✕
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto px-5 py-4">
          {showWizard && date ? (
            <AppointmentWizard
              date={date}
              onDone={() => setShowWizard(false)}
              onCancel={() => setShowWizard(false)}
            />
          ) : sorted.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full gap-4 text-center">
              <p className="text-gray-400 text-sm">No appointments for this day</p>
              <button
                onClick={() => setShowWizard(true)}
                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors"
              >
                + Add Appointment
              </button>
            </div>
          ) : (
            <div className="flex flex-col gap-3">
              {sorted.map(appt => (
                <div
                  key={appt.id}
                  className="flex items-start gap-3 p-3 rounded-lg border border-gray-100 hover:border-gray-200 bg-white transition-colors"
                >
                  <span className="text-xs font-mono text-gray-500 mt-0.5 flex-shrink-0 w-12">
                    {appt.timeSlot}
                  </span>
                  <div
                    className="flex-1 min-w-0 cursor-pointer"
                    onClick={() => setSelectedAppt(appt)}
                  >
                    <p className="text-sm font-medium text-gray-800 truncate">{appt.clientName}</p>
                    <p className="text-xs text-gray-500 truncate capitalize">
                      {appt.serviceType.replace(/-/g, " ")}
                    </p>
                  </div>
                  <div className="flex items-center gap-2 flex-shrink-0">
                    <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${STATUS_COLORS[appt.status]}`}>
                      {STATUS_LABELS[appt.status]}
                    </span>
                    <SendPortalButton appt={appt} />
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {!showWizard && (
          <div className="px-5 py-4 border-t border-gray-100 flex-shrink-0">
            <button
              onClick={() => setShowWizard(true)}
              className="w-full py-2 px-4 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors"
            >
              + New Appointment
            </button>
          </div>
        )}
      </div>

      {selectedAppt && (
        <AppointmentDetailModal
          appointment={selectedAppt}
          onClose={() => setSelectedAppt(null)}
          onStatusChange={onStatusChange}
        />
      )}
    </>
  )
}
