import { useState, useEffect } from "react"
import {
  collection,
  query,
  where,
  onSnapshot,
  updateDoc,
  doc,
  Timestamp,
} from "firebase/firestore"
import { startOfMonth, endOfMonth } from "date-fns"
import { db } from "../firebase/config"

export type AppointmentStatus =
  | "scheduled"
  | "confirmed"
  | "in-progress"
  | "completed"
  | "cancelled"
  | "pending-approval"

export interface Appointment {
  id: string
  clientId: string
  clientName: string
  date: Date
  timeSlot: string
  status: AppointmentStatus
  serviceType: string
  estimatedDuration: number
  notes: string
  clientConfirmedAt: null
  clientCancelledAt: null
  createdAt: Date
  updatedAt: Date
}

interface UseAppointmentsResult {
  appointments: Appointment[]
  loading: boolean
  error: string | null
  moveAppointment: (appointmentId: string, newDate: Date) => Promise<void>
  updateAppointmentStatus: (appointmentId: string, status: AppointmentStatus) => Promise<void>
}

export function useAppointments(year: number, month: number): UseAppointmentsResult {
  const [appointments, setAppointments] = useState<Appointment[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (!db) {
      setLoading(false)
      return
    }

    const monthStart = startOfMonth(new Date(year, month, 1))
    const monthEnd = endOfMonth(new Date(year, month, 1))

    const q = query(
      collection(db, "appointments"),
      where("date", ">=", Timestamp.fromDate(monthStart)),
      where("date", "<=", Timestamp.fromDate(monthEnd))
    )

    const unsubscribe = onSnapshot(
      q,
      snapshot => {
        const data: Appointment[] = snapshot.docs.map(d => {
          const raw = d.data()
          return {
            id: d.id,
            clientId: raw.clientId,
            clientName: raw.clientName,
            date: (raw.date as Timestamp).toDate(),
            timeSlot: raw.timeSlot,
            status: raw.status as AppointmentStatus,
            serviceType: raw.serviceType,
            estimatedDuration: raw.estimatedDuration,
            notes: raw.notes,
            clientConfirmedAt: null,
            clientCancelledAt: null,
            createdAt: (raw.createdAt as Timestamp).toDate(),
            updatedAt: (raw.updatedAt as Timestamp).toDate(),
          }
        })
        setAppointments(data)
        setLoading(false)
      },
      err => {
        setError(err.message)
        setLoading(false)
      }
    )

    return unsubscribe
  }, [year, month])

  async function moveAppointment(appointmentId: string, newDate: Date): Promise<void> {
    if (!db) return

    // Optimistic update
    setAppointments(prev =>
      prev.map(a =>
        a.id === appointmentId ? { ...a, date: newDate } : a
      )
    )

    try {
      await updateDoc(doc(db, "appointments", appointmentId), {
        date: Timestamp.fromDate(newDate),
        updatedAt: Timestamp.now(),
      })
    } catch (err) {
      // Revert on failure — will be corrected by next onSnapshot emission
      throw err
    }
  }

  async function updateAppointmentStatus(appointmentId: string, status: AppointmentStatus): Promise<void> {
    if (!db) return
    setAppointments(prev =>
      prev.map(a => a.id === appointmentId ? { ...a, status } : a)
    )
    await updateDoc(doc(db, "appointments", appointmentId), {
      status,
      updatedAt: Timestamp.now(),
    })
  }

  return { appointments, loading, error, moveAppointment, updateAppointmentStatus }
}
