import React, { useState, useCallback } from "react"
import { graphql } from "gatsby"
import {
  DndContext,
  DragEndEvent,
  DragOverlay,
  PointerSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core"
import { format, isSameMonth } from "date-fns"
import { useRequireAuth } from "../../hooks/useRequireAuth"
import { useAppointments, Appointment } from "../../hooks/useAppointments"
import { useToast } from "../../context/ToastContext"
import { toDateKey } from "../../utils/dateUtils"
import AdminLayout from "../../components/admin/AdminLayout"
import CalendarGrid from "../../components/admin/Calendar/CalendarGrid"
import DayPanel from "../../components/admin/Calendar/DayPanel"

interface PendingMove {
  appt: Appointment
  targetDate: Date
}

export default function AdminDashboard() {
  const { currentUser, loading } = useRequireAuth()

  const today = new Date()
  const [year, setYear] = useState(today.getFullYear())
  const [month, setMonth] = useState(today.getMonth())
  const [selectedDate, setSelectedDate] = useState<Date | null>(null)
  const [activeAppt, setActiveAppt] = useState<Appointment | null>(null)
  const [pendingMove, setPendingMove] = useState<PendingMove | null>(null)

  const { appointments, loading: apptLoading, moveAppointment, updateAppointmentStatus } = useAppointments(year, month)
  const { showToast } = useToast()

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }))

  const handleDayClick = useCallback((date: Date) => {
    setSelectedDate(date)
  }, [])

  const handleMonthChange = useCallback((y: number, m: number) => {
    setYear(y)
    setMonth(m)
    setSelectedDate(null)
  }, [])

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      setActiveAppt(null)
      const { active, over } = event
      if (!over || active.id === over.id) return

      const [oy, om, od] = (over.id as string).split("-").map(Number)
      const targetDate = new Date(oy, om - 1, od)

      if (!isSameMonth(targetDate, new Date(year, month, 1))) return

      const appt = appointments.find(a => a.id === active.id)
      if (!appt) return

      if (toDateKey(appt.date) === toDateKey(targetDate)) return

      // Show confirmation dialog instead of moving immediately
      setPendingMove({ appt, targetDate })
    },
    [appointments, year, month]
  )

  async function confirmMove() {
    if (!pendingMove) return
    const { appt, targetDate } = pendingMove
    setPendingMove(null)
    try {
      await moveAppointment(appt.id, targetDate)
      showToast(`Appointment moved to ${format(targetDate, "MMM d")}`, "success")
    } catch {
      showToast("Failed to move appointment. Please try again.", "error")
    }
  }

  const dayAppointments = selectedDate
    ? appointments.filter(a => toDateKey(a.date) === toDateKey(selectedDate))
    : []

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  if (!currentUser) return null

  return (
    <AdminLayout currentPath="/admin/dashboard">
      <DndContext
        sensors={sensors}
        onDragStart={event => {
          const appt = appointments.find(a => a.id === event.active.id)
          setActiveAppt(appt ?? null)
        }}
        onDragEnd={handleDragEnd}
        onDragCancel={() => setActiveAppt(null)}
      >
        <div className="flex gap-0">
          <div className="flex-1 min-w-0">
            {apptLoading ? (
              <div className="flex items-center justify-center h-64">
                <div className="w-6 h-6 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
              </div>
            ) : (
              <CalendarGrid
                year={year}
                month={month}
                appointments={appointments}
                selectedDate={selectedDate}
                onDayClick={handleDayClick}
                onMonthChange={handleMonthChange}
              />
            )}
          </div>

          <DayPanel
            date={selectedDate}
            appointments={dayAppointments}
            onClose={() => setSelectedDate(null)}
            onStatusChange={updateAppointmentStatus}
          />
        </div>

        <DragOverlay>
          {activeAppt ? (
            <div className="text-xs px-2 py-1 rounded bg-blue-200 text-blue-900 shadow-lg cursor-grabbing">
              {activeAppt.timeSlot} {activeAppt.clientName.split(" ")[0]}
            </div>
          ) : null}
        </DragOverlay>
      </DndContext>

      {/* Move confirmation dialog */}
      {pendingMove && (
        <div className="fixed inset-0 bg-black/40 z-50 flex items-center justify-center px-4">
          <div className="bg-white rounded-2xl shadow-xl p-6 w-full max-w-sm">
            <h2 className="text-base font-semibold text-gray-800 mb-2">Move Appointment</h2>
            <p className="text-sm text-gray-600 mb-1">
              <span className="font-medium">{pendingMove.appt.clientName}</span>
              {" — "}{pendingMove.appt.serviceType}
            </p>
            <p className="text-sm text-gray-500 mb-5">
              Move from{" "}
              <span className="font-medium text-gray-700">
                {format(pendingMove.appt.date, "MMM d")}
              </span>{" "}
              to{" "}
              <span className="font-medium text-gray-700">
                {format(pendingMove.targetDate, "MMM d")}
              </span>
              ?
            </p>
            <div className="flex gap-3">
              <button
                onClick={() => setPendingMove(null)}
                className="flex-1 py-2 px-4 border border-gray-300 text-gray-700 text-sm font-medium rounded-lg hover:bg-gray-50 transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={confirmMove}
                className="flex-1 py-2 px-4 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors"
              >
                Move
              </button>
            </div>
          </div>
        </div>
      )}
    </AdminLayout>
  )
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`
