import {
  collection,
  query,
  where,
  getDocs,
  addDoc,
  updateDoc,
  doc,
  arrayUnion,
  Timestamp,
} from "firebase/firestore"
import { nanoid } from "nanoid"
import { db } from "../firebase/config"

export interface Vehicle {
  vehicleId: string
  make: string
  model: string
  year: number
  color: string
  notes: string
}

export interface Client {
  id: string
  name: string
  phone: string
  email: string
  address: string
  vehicles: Vehicle[]
  portalTokens: unknown[]
  createdAt: Date
  updatedAt: Date
}

export type NewClientData = Omit<Client, "id" | "vehicles" | "portalTokens" | "createdAt" | "updatedAt">
export type NewVehicleData = Omit<Vehicle, "vehicleId">

// Firestore does not support full-text search. This implementation uses prefix
// match on the `nameLower` field (stored lowercase) for case-insensitive search.
// For advanced search consider Algolia or Typesense.
export async function searchClients(q: string): Promise<Client[]> {
  if (!db || !q.trim()) return []

  const isPhone = /^[\d\s\-+()\*]+$/.test(q)
  const colRef = collection(db, "clients")

  let fsQuery
  if (isPhone) {
    fsQuery = query(colRef, where("phone", ">=", q), where("phone", "<=", q + ""))
  } else {
    const lower = q.toLowerCase()
    fsQuery = query(colRef, where("nameLower", ">=", lower), where("nameLower", "<=", lower + ""))
  }

  const snap = await getDocs(fsQuery)
  return snap.docs.map(d => {
    const data = d.data()
    return {
      id: d.id,
      name: data.name,
      phone: data.phone,
      email: data.email,
      address: data.address,
      vehicles: data.vehicles ?? [],
      portalTokens: data.portalTokens ?? [],
      createdAt: (data.createdAt as Timestamp).toDate(),
      updatedAt: (data.updatedAt as Timestamp).toDate(),
    }
  })
}

export async function createClient(data: NewClientData): Promise<Client> {
  if (!db) throw new Error("Firestore not initialized")

  const now = Timestamp.now()
  const docRef = await addDoc(collection(db, "clients"), {
    ...data,
    nameLower: data.name.toLowerCase(),
    vehicles: [],
    portalTokens: [],
    createdAt: now,
    updatedAt: now,
  })

  return {
    id: docRef.id,
    ...data,
    vehicles: [],
    portalTokens: [],
    createdAt: now.toDate(),
    updatedAt: now.toDate(),
  }
}

export async function updateClient(clientId: string, data: Partial<NewClientData>): Promise<void> {
  if (!db) throw new Error("Firestore not initialized")
  await updateDoc(doc(db, "clients", clientId), {
    ...data,
    ...(data.name ? { nameLower: data.name.toLowerCase() } : {}),
    updatedAt: Timestamp.now(),
  })
}

export async function removeVehicle(clientId: string, vehicleId: string, currentVehicles: Vehicle[]): Promise<void> {
  if (!db) throw new Error("Firestore not initialized")
  const updated = currentVehicles.filter(v => v.vehicleId !== vehicleId)
  await updateDoc(doc(db, "clients", clientId), {
    vehicles: updated,
    updatedAt: Timestamp.now(),
  })
}

export async function addVehicle(clientId: string, vehicleData: NewVehicleData): Promise<Vehicle> {
  if (!db) throw new Error("Firestore not initialized")

  const vehicle: Vehicle = {
    vehicleId: nanoid(),
    ...vehicleData,
  }

  await updateDoc(doc(db, "clients", clientId), {
    vehicles: arrayUnion(vehicle),
    updatedAt: Timestamp.now(),
  })

  return vehicle
}
